    for _ in range(n):
        a, b = b, a + b
    return a

def primes_up_to(n: int) -> list[int]:
    if n < 2:
        return []
    sieve = bytearray(b"\x01") * (n + 1)
    sieve[0:2] = b"\x00\x00"
    limit = int(n ** 0.5)
    for p in range(2, limit + 1):
        if sieve[p]:
            start = p * p
            sieve[start:n + 1:p] = b"\x00" * (((n - start) // p) + 1)
    return [i for i in range(2, n + 1) if sieve[i]]

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n in (2, 3):
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    i = 5
    step = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += step
        step = 6 - step

    return True

def most_common_word(t: str) -> str:
    words = t.lower().split()
    if not words:
        return ""
    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    max_count = max(counts.values())
    return min(w for w, c in counts.items() if c == max_count)

def run_length_encode(t: str) -> str:
    if not t:
        return ""
    result = []
    current = t[0]
    count = 1
    for ch in t[1:]:
        if ch == current:
            count += 1
        else:
            result.append(current)
            result.append(str(count))
            current = ch
            count = 1
    result.append(current)
    result.append(str(count))
    return "".join(result)

def caesar_shift(t: str, k: int) -> str:
    k %= 26
    out = []
    for ch in t:
        if 'a' <= ch <= 'z':
            out.append(chr((ord(ch) - ord('a') + k) % 26 + ord('a')))
        else:
            out.append(ch)
    return ''.join(out)

def find_sorted(xs: list[int], x: int) -> int:
    lo, hi = 0, len(xs)
    while lo < hi:
        mid = (lo + hi) // 2
        if xs[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo if lo < len(xs) and xs[lo] == x else -1

def two_sum(xs: list[int], target: int) -> list[int]:
    seen = {}
    best = None

    for j, x in enumerate(xs):
        need = target - x
        if need in seen:
            i = seen[need]
            if best is None or i < best[0] or (i == best[0] and j < best[1]):
                best = (i, j)
        if x not in seen:
            seen[x] = j

    return [] if best is None else [best[0], best[1]]

def balanced_brackets(t: str) -> bool:
    stack = []
    matching = {')': '(', ']': '[', '}': '{'}
    opening = set(matching.values())

    for ch in t:
        if ch in opening:
            stack.append(ch)
        elif ch in matching:
            if not stack or stack.pop() != matching[ch]:
                return False

    return not stack

def collatz_steps(n: int) -> int:
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n //= 2
        else:
            n = 3 * n + 1
        steps += 1
    return steps

def to_binary(n: int) -> str:
    if n == 0:
        return "0"
    bits = []
    while n > 0:
        bits.append("1" if n & 1 else "0")
        n >>= 1
    return "".join(reversed(bits))

