        return []
    return [list(row) for row in zip(*m)]

def second_largest(xs: list[int]) -> int:
    if len(xs) < 2:
        raise ValueError

    largest = None
    second = None

    for x in xs:
        if largest is None or x > largest:
            if largest is None or x != largest:
                second = largest
                largest = x
        elif x != largest and (second is None or x > second):
            second = x

    if second is None:
        raise ValueError

    return second

def longest_common_prefix(words: list[str]) -> str:
    if not words:
        return ""
    prefix = words[0]
    for word in words[1:]:
        i = 0
        limit = min(len(prefix), len(word))
        while i < limit and prefix[i] == word[i]:
            i += 1
        prefix = prefix[:i]
        if not prefix:
            break
    return prefix

