def eval_rpn(tokens: list[str]) -> int:
    stack = []

    for token in tokens:
        if token in {"+", "-", "*"}:
            if len(stack) < 2:
                raise ValueError("not enough operands")
            rhs = stack.pop()
            lhs = stack.pop()
            if token == "+":
                stack.append(lhs + rhs)
            elif token == "-":
                stack.append(lhs - rhs)
            else:
                stack.append(lhs * rhs)
        else:
            try:
                stack.append(int(token))
            except ValueError:
                raise ValueError("invalid token") from None

    if len(stack) != 1:
        raise ValueError("stack does not contain exactly one value")

    return stack[0]

def final_position(moves: str) -> list[int]:
    x = 0
    y = 0
    for ch in moves:
        if ch == 'U':
            y += 1
        elif ch == 'D':
            y -= 1
        elif ch == 'R':
            x += 1
        elif ch == 'L':
            x -= 1
    return [x, y]

