from collections import defaultdict


def two_sum(xs: list[int], target: int) -> list[int]:
    lookup = defaultdict(list)
    for idx, val in enumerate(xs):
        lookup[val].append(idx)

    for i, val in enumerate(xs):
        needed = target - val
        if needed in lookup:
            indices = lookup[needed]
            j_pos = bisect.bisect_right(indices, i)
            if j_pos < len(indices):
                return [i, indices[j_pos]]

    return []

