def eval_rpn(tokens: list[str]) -> int:
    stack: list[int] = []
    for token in tokens:
        if token in ('+', '-', '*'):
            if len(stack) < 2:
                raise ValueError("Not enough operands for operator")
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
        else:
            try:
                val = int(token)
            except ValueError:
                raise ValueError(f"Invalid token: {token}")
            stack.append(val)

    if len(stack) != 1:
        raise ValueError(f"Expected exactly one value on stack, found {len(stack)}")

    return stack[0]

def sum_csv(t: str) -> int:
    pieces = t.split(",")
    total = 0
    for piece in pieces:
        s = piece.strip()
        if not s:
            raise ValueError(f"Empty piece: {piece!r}")
        s_num = s[1:] if s[0] in "+-" else s
        if not s_num or not s_num.isdigit() or not s_num.isascii():
            raise ValueError(f"Invalid whole number: {piece!r}")
        total += int(s)
    return total
